sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {
    var body = request.body.data;
    var orderValue = body.order_value;
    var complaintType = body.complaint_type || '';
    var userId = body.user_id || gs.getUserID();

    if (!orderValue && orderValue !== 0) {
        response.setStatus(400);
        response.setBody({ error: 'order_value is required' });
        return;
    }

    var utils = new x_2145749_qc.VaAgentUtils();
    var prediction = utils.predictResolution(orderValue, complaintType, userId);

    response.setStatus(200);
    response.setBody({
        result: prediction,
        inputs: {
            order_value: orderValue,
            complaint_type: complaintType,
            auto_approve_ceiling: utils.AUTO_APPROVE_CEILING
        }
    });
})(request, response)
